import React, { useState, useEffect } from "react";
import { Alert, Button } from "react-bootstrap";

const CookiesBanner = () => {
  const [show, setShow] = useState(false);

  useEffect(() => {
    const consent = localStorage.getItem("cookieConsent");
    const dismissed = sessionStorage.getItem("cookieDismissed");
    let timer;
    if (consent === null && dismissed === null) {
      timer = setTimeout(() => {
        setShow(true);
      }, 2000);
    }
    return () => clearTimeout(timer);
  }, []);

  const handleConsent = (granted) => {
    localStorage.setItem("cookieConsent", granted ? "true" : "false");
    setShow(false);
  };

  const handleDismiss = () => {
    sessionStorage.setItem("cookieDismissed", "true");
    setShow(false);
  };

  return (
    <>
      {show && (
        <Alert
          variant="secondary"
          className="rounded-0 w-100 position-fixed mb-0 text-align-center d-flex align-items-center justify-content-around"
          style={{ zIndex: 1051, bottom: 0, left: 0 }}
          dismissible
          onClose={handleDismiss}
        >
          <p>
            {/* We use cookies to enhance your experience. By continuing to visit
            this site, you agree to our use of cookies. */}
            Χρησιμοποιούμε cookies για να βελτιώσουμε την εμπειρία σας.
            Συνεχίζοντας να επισκέπτεστε αυτό το site, συμφωνείτε με τη χρήση
            των cookies.
          </p>
          <div className="ml-3">
            <Button
              className="mr-3 mt-3 w-100"
              variant="outline-primary"
              onClick={handleConsent.bind(null, true)}
            >
              {/* Accept */}
              ΑΠΟΔΟΧΗ
            </Button>
            <Button
              className="mt-3 w-100"
              variant="outline-secondary"
              onClick={handleConsent.bind(null, false)}
            >
              {/* Reject */}
              ΑΠΟΡΡΙΨΗ
            </Button>
          </div>
        </Alert>
      )}
    </>
  );
};

export default CookiesBanner;
